using Dapper; using Sigov.Application.Agro.Agroindustrias; using Sigov.Application.Common; using Sigov.Infrastructure.Persistence.Dapper;
namespace Sigov.Infrastructure.Agro.Repositories;
public sealed class AgroAgroindustriaRepository:IAgroAgroindustriaRepository{private readonly DapperContext _c; public AgroAgroindustriaRepository(DapperContext c)=>_c=c; public async Task<PagedResult<AgroAgroindustriaResponse>> ListarAsync(long t,long e,int p,int ps,CancellationToken ct){using var cn=_c.CreateConnection(); var rows=await cn.QueryAsync<AgroAgroindustriaResponse>(new CommandDefinition("select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,tipo_atividade TipoAtividade,situacao,latitude,longitude,ativo from sigov.agro_agroindustria where tenant_id=@t and entidade_id=@e and is_deleted=false order by created_at desc limit @ps offset @o",new{t,e,ps,o=(p-1)*ps},cancellationToken:ct)); return new(rows.AsList(),p,ps,rows.Count());} public async Task<AgroAgroindustriaResponse?> ObterAsync(long t,long e,long id,CancellationToken ct){using var cn=_c.CreateConnection(); return await cn.QuerySingleOrDefaultAsync<AgroAgroindustriaResponse>(new CommandDefinition("select id,tenant_id TenantId,entidade_id EntidadeId,codigo,nome,tipo_atividade TipoAtividade,situacao,latitude,longitude,ativo from sigov.agro_agroindustria where tenant_id=@t and entidade_id=@e and id=@id and is_deleted=false",new{t,e,id},cancellationToken:ct));} public async Task<long> CriarAsync(long t,long e,long? u,AgroAgroindustriaCreateRequest r,CancellationToken ct){using var cn=_c.CreateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.agro_agroindustria(tenant_id,entidade_id,produtor_id,pessoa_id,codigo,nome,tipo_atividade,endereco_json,latitude,longitude,situacao,licenca_sanitaria,registro_sim,observacao,created_by) values(@t,@e,@ProdutorId,@PessoaId,@Codigo,@Nome,@TipoAtividade,coalesce(@EnderecoJson::jsonb,'{}'::jsonb),@Latitude,@Longitude,@Situacao,@LicencaSanitaria,@RegistroSim,@Observacao,@u) returning id",new{t,e,u,r.ProdutorId,r.PessoaId,r.Codigo,r.Nome,r.TipoAtividade,r.EnderecoJson,r.Latitude,r.Longitude,r.Situacao,r.LicencaSanitaria,r.RegistroSim,r.Observacao},cancellationToken:ct));} public async Task AtualizarAsync(long t,long e,long id,long? u,AgroAgroindustriaCreateRequest r,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_agroindustria set codigo=@Codigo,nome=@Nome,tipo_atividade=@TipoAtividade,situacao=@Situacao,updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,u,r.Codigo,r.Nome,r.TipoAtividade,r.Situacao},cancellationToken:ct));} public async Task ExcluirAsync(long t,long e,long id,long? u,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_agroindustria set is_deleted=true,ativo=false,deleted_at=now(),deleted_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,u},cancellationToken:ct));} public async Task<PagedResult<AgroInspecaoMunicipalResponse>> ListarInspecoesAsync(long t,long e,long ag,CancellationToken ct){using var cn=_c.CreateConnection(); var rows=await cn.QueryAsync<AgroInspecaoMunicipalResponse>(new CommandDefinition("select id,tenant_id TenantId,entidade_id EntidadeId,agroindustria_id AgroindustriaId,numero,data_inspecao DataInspecao,resultado,prazo_adequacao PrazoAdequacao,status,ativo from sigov.agro_inspecao_municipal where tenant_id=@t and entidade_id=@e and agroindustria_id=@ag and is_deleted=false",new{t,e,ag},cancellationToken:ct)); return new(rows.AsList(),1,100,rows.Count());} public async Task<long> CriarInspecaoAsync(long t,long e,long ag,long? u,AgroInspecaoMunicipalCreateRequest r,CancellationToken ct){using var cn=_c.CreateConnection(); return await cn.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.agro_inspecao_municipal(tenant_id,entidade_id,agroindustria_id,numero,data_inspecao,inspetor_usuario_id,resultado,observacoes,exigencias_json,prazo_adequacao,status,created_by) values(@t,@e,@ag,@Numero,@DataInspecao,@InspetorUsuarioId,@Resultado,@Observacoes,coalesce(@ExigenciasJson::jsonb,'[]'::jsonb),@PrazoAdequacao,@Status,@u) returning id",new{t,e,ag,u,r.Numero,r.DataInspecao,r.InspetorUsuarioId,r.Resultado,r.Observacoes,r.ExigenciasJson,r.PrazoAdequacao,r.Status},cancellationToken:ct));} public async Task ConcluirInspecaoAsync(long t,long e,long id,long? u,CancellationToken ct){using var cn=_c.CreateConnection(); await cn.ExecuteAsync(new CommandDefinition("update sigov.agro_inspecao_municipal set status='CONCLUIDA',updated_at=now(),updated_by=@u where tenant_id=@t and entidade_id=@e and id=@id",new{t,e,id,u},cancellationToken:ct));}}
